using System.Security.Cryptography; namespace CubeAntivirus.Core; public sealed class QuarantineManager { public string Folder { get; } = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "CubeAntivirus", "IsolatedSandbox"); public QuarantineManager() => Directory.CreateDirectory(Folder); public async Task<string> CopyToQuarantineAsync(string source, CancellationToken token = default) { if (!File.Exists(source)) throw new FileNotFoundException("File not found.", source); await using var input = new FileStream(source, FileMode.Open, FileAccess.Read, FileShare.Read); var hash = Convert.ToHexString(await SHA256.HashDataAsync(input, token)); var destination = Path.Combine(Folder, hash + ".quarantine"); input.Position = 0; await using var output = new FileStream(destination, FileMode.CreateNew, FileAccess.Write, FileShare.None); await input.CopyToAsync(output, token); return destination; } }